import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { createLocalServer, LocalStorage } from '../local.mjs';
import { validateSnapshot, ChannelHandler } from '../src/worker.js';

// Supply matching Rust encode_binary(base), encode_binary(target), and
// encode_delta(target, base). These are intentionally not generated by this test.
const deltaPath = process.env.BMWP3_DELTA_FIXTURE;
const targetPath = process.env.BMWP3_TARGET_FIXTURE;
test('real Rust delta exact base admission and full repair survive relay selection',
  { skip: !(process.env.BMWP3_FIXTURE && deltaPath && targetPath) && 'set BMWP3_FIXTURE, BMWP3_TARGET_FIXTURE, BMWP3_DELTA_FIXTURE' }, async () => {
    const base = new Uint8Array(await readFile(process.env.BMWP3_FIXTURE));
    const full = new Uint8Array(await readFile(targetPath));
    const delta = new Uint8Array(await readFile(deltaPath));
    const identity = validateSnapshot(base); validateSnapshot(full);
    assert.ok(delta.length < full.length, 'fixture must exercise smaller delta');
    const key = 'cross-language-delta-only-test';
    const storage = { async get() { return this.value; }, async put(_key, value) { this.value = structuredClone(value); } };
    const handler = new ChannelHandler(storage, { CHANNEL: 'main', DELTA_BUNDLES: 'fanout', PUBLISHER_KEY_SHA256: createHash('sha256').update(key).digest('hex') });
    const cap = { 'X-Bmux-Capabilities': 'bmwp-delta-v1' };
    const auth = { Authorization: `Bearer ${key}` };
    const url = 'https://relay.test/api/live/main/';
    const started = await handler.fetch(new Request(`${url}publisher/start`, { method: 'POST', headers: { ...auth, ...cap, 'Content-Type': 'application/json' },
      body: JSON.stringify({ protocol: 1, renderer: 'bmwp-3', publisher_id: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' }) }));
    assert.equal(started.status, 200); const { epoch } = await started.json();
    const upload = (body, revision, extra = {}) => handler.fetch(new Request(`${url}publisher/frame`, { method: 'PUT',
      headers: { ...auth, 'Content-Type': 'application/octet-stream', 'X-Bmux-Epoch': epoch, 'X-Bmux-Revision': revision, ...extra }, body }));
    assert.equal((await upload(base, '1')).status, 204);
    const body = new Uint8Array(4 + full.length + delta.length);
    new DataView(body.buffer).setUint32(0, full.length, true); body.set(full, 4); body.set(delta, 4 + full.length);
    assert.equal((await upload(body, '2', { ...cap, 'X-Bmux-Base-Revision': '1' })).status, 204);
    const selected = await handler.fetch(new Request(`${url}presentation?epoch=${epoch}&after=1&generation=${encodeURIComponent(identity.generation)}&base=${identity.revision}`, { headers: cap }));
    assert.equal(selected.status, 200); assert.equal(selected.headers.get('X-Bmux-Frame'), 'delta');
    assert.deepEqual(new Uint8Array(await selected.arrayBuffer()), delta);
    for (const headers of [cap, {}]) {
      const repaired = await handler.fetch(new Request(`${url}presentation?epoch=${epoch}`, { headers }));
      assert.deepEqual(new Uint8Array(await repaired.arrayBuffer()), full);
    }
  });

// No inferred path or fabricated semantic fixture. Coordinator supplies real
// encode_binary[_with_resources] output after the Rust build reservation.
const path = process.env.BMWP3_FIXTURE;
test('external Rust BMWP3 full snapshot survives real HTTP relay byte-for-byte', { skip: !path && 'set BMWP3_FIXTURE to Rust-produced binary' }, async () => {
  const bytes = new Uint8Array(await readFile(path));
  validateSnapshot(bytes);
  const key = 'isolated-cross-language-test';
  const env = { CHANNEL: 'main', PUBLISHER_KEY_SHA256: createHash('sha256').update(key).digest('hex') };
  const storage = new LocalStorage();
  const running = await createLocalServer({ env, storage });
  const url = `${running.url}/api/live/main`;
  const auth = { Authorization: `Bearer ${key}` };
  try {
    const started = await fetch(`${url}/publisher/start`, { method: 'POST', headers: { ...auth, 'Content-Type': 'application/json' }, body: JSON.stringify({ protocol: 1, renderer: 'bmwp-3', publisher_id: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' }) });
    assert.equal(started.status, 200);
    const { epoch } = await started.json();
    const uploaded = await fetch(`${url}/publisher/frame`, { method: 'PUT', headers: { ...auth, 'X-Bmux-Epoch': epoch, 'X-Bmux-Revision': '1', 'Content-Type': 'application/octet-stream' }, body: bytes });
    assert.equal(uploaded.status, 204);
    const status = await (await fetch(`${url}/status`)).json();
    assert.equal(status.state, 'live'); assert.equal(status.revision, '1');
    const frame = await fetch(`${url}/presentation?epoch=${epoch}`);
    assert.equal(frame.status, 200); assert.equal(frame.headers.get('Content-Type'), 'application/octet-stream');
    assert.equal(frame.headers.get('X-Snapshot-Revision'), '1');
    assert.deepEqual(new Uint8Array(await frame.arrayBuffer()), bytes);
    // Fixture includes arbitrary image payloads, so exact bytes check is vital.
    assert.ok(JSON.stringify(storage.value).length < 1024);
  } finally { await new Promise(r => { running.server.close(r); running.server.closeAllConnections(); }); }
});
